def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    divisor = D(n)
    # Handle the case where divisor is 0, though unlikely for n >= 0
    if divisor == 0:
        return False # Or handle based on problem constraints, but D(n) > 0 for n >= 0

    numerator = 20**(n + 1)

    # Check if numerator is divisible by divisor
    return numerator % divisor == 0

results = {}
for n in range(16):
    is_divisible = check_divisibility(n)
    results[n] = is_divisible

print(results)
